mes = load_days(); mgc = mgc_days(True)
def cp(k, n, a=0.05): return (beta.ppf(a / 2, k, n - k + 1) if k > 0 else 0.0, beta.ppf(1 - a / 2, k + 1, n - k) if k < n else 1.0)
P("# resultados_H4 — noticias como filtro y como riesgo\n")
